export const reversingExercises: Exercise[] = [
  {"id":"re-identifier-un-prologue-de-fonction-x64","type":"mcq","domain":"software","topic":"reversing","difficulty":"intermediate","title":"Identifier un prologue de fonction x64","company":"Practical Binary Analysis ch.1 — Anatomy of a Binary","scenario":"push rbp\nmov rbp, rsp\nsub rsp, 0x20","question":"Que réalise ce fragment situé en tête d'une fonction ?","options":["Prologue de fonction : sauvegarde du RBP appelant et réservation de 32 octets de variables locales","Épilogue de fonction restaurant RBP puis dépilant l'adresse de retour vers RIP","Passage de trois arguments sur la pile selon la convention cdecl avant un CALL","Réservation du shadow space de 32 octets exigé par la convention System V AMD64"],"answer":0,"explanation":"push rbp/mov rbp,rsp établit le frame pointer, puis sub rsp,0x20 alloue l'espace des locales. C'est le prologue classique. Le shadow space de 32 octets existe sous Windows x64, pas System V ; et il est réservé par l'appelant, pas dans le prologue de l'appelé.","tags":["x64","prologue","stack-frame","assembleur"],"optionNotes":["push rbp/mov rbp,rsp pose le frame pointer, sub rsp,0x20 reserve 32 octets de locales : prologue.","Un epilogue ferait l'inverse (mov rsp,rbp/pop rbp/ret) ; ici on installe le cadre, on ne le defait pas.","cdecl empilerait les args (push) ; sub rsp reserve un espace, ce n'est pas passer des arguments.","Le shadow space est propre a Windows x64, pas a System V, et c'est l'appelant qui le reserve."]},
  {"id":"re-qui-nettoie-la-pile-en-stdcall","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"Qui nettoie la pile en stdcall","company":"Reversing: Secrets of Reverse Engineering ch.5","scenario":"...\ncall _MessageBoxA@16\n; l'instruction suivante n'ajuste PAS ESP","question":"Le symbole importé se termine par @16 et aucun add esp,N ne suit le CALL. Quelle convention est employée ?","options":["stdcall : l'appelé dépile lui-même les arguments via ret 16","cdecl : l'appelant nettoie mais le compilateur a fusionné le add esp","fastcall : les quatre premiers arguments passent par ECX et EDX","thiscall : ECX porte le this et l'appelant nettoie le reste"],"answer":0,"explanation":"Le décorateur @16 (nom + taille cumulée des arguments) et l'absence d'ajustement d'ESP après le CALL trahissent stdcall : la fonction se termine par ret 16, dépilant elle-même les 16 octets d'arguments. En cdecl l'appelant émettrait add esp,16.","tags":["stdcall","calling-convention","x86","name-decoration"],"optionNotes":["Le decorateur @16 et l'absence d'add esp signent stdcall : l'appele depile via ret 16.","En cdecl l'appelant emettrait un add esp,16 visible ; aucun compilateur ne le 'fusionne' silencieusement.","fastcall passerait des args par ECX/EDX, mais @16 denote un depilement par l'appele, pas fastcall.","thiscall utilise ECX pour this ; rien ici n'indique un objet, et @16 pointe stdcall."]},
  {"id":"re-ordre-des-arguments-system-v-amd64","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"Ordre des arguments System V AMD64","company":"Practical Binary Analysis ch.2 — The ELF Format","question":"Sous l'ABI System V AMD64 (Linux), dans quel ordre les six premiers arguments entiers sont-ils passés ?","options":["RDI, RSI, RDX, RCX, R8, R9","RCX, RDX, R8, R9, puis pile","RAX, RBX, RCX, RDX, RSI, RDI","RSI, RDI, RCX, RDX, R9, R8"],"answer":0,"explanation":"System V AMD64 passe les six premiers entiers dans RDI, RSI, RDX, RCX, R8, R9 ; les suivants sur la pile. RCX/RDX/R8/R9 est l'ordre Windows x64. Reconnaître RDI comme premier argument est essentiel pour reverser du code Linux.","tags":["x64","system-v","calling-convention","elf"],"optionNotes":["System V AMD64 : RDI, RSI, RDX, RCX, R8, R9 pour les six premiers entiers, puis la pile.","RCX, RDX, R8, R9 est l'ordre Windows x64, pas System V (Linux).","RAX sert au retour/syscall, pas au 1er argument ; cet ordre n'existe dans aucune ABI.","Ordre invente : RSI/RDI sont inverses et R9 precede R8, ce n'est pas l'ABI System V."]},
  {"id":"re-shadow-space-windows-x64","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"Shadow space Windows x64","company":"Practical Malware Analysis ch.21 — 64-bit Malware","scenario":"sub rsp, 0x28\nmov rcx, rbx\ncall SomeApi\nadd rsp, 0x28","question":"Pourquoi 0x28 octets sont-ils réservés avant l'appel alors qu'un seul argument (RCX) est utilisé ?","options":["0x20 de shadow space obligatoire plus 8 octets d'alignement de la pile sur 16","0x28 correspond aux cinq arguments empilés que l'API attend en mémoire","La zone stocke les registres volatils sauvegardés avant le CALL","C'est l'espace des variables locales de la fonction appelée, pré-alloué"],"answer":0,"explanation":"La convention Windows x64 impose 32 octets (0x20) de shadow space que l'appelant réserve même si les arguments tiennent dans les registres. Les 8 octets supplémentaires réalignent RSP sur 16 octets, exigence de l'ABI au moment du CALL (RSP+8 après le push implicite de l'adresse de retour).","tags":["x64","windows","shadow-space","stack-alignment"],"optionNotes":["0x20 de shadow space obligatoire + 8 octets pour realigner RSP sur 16 au moment du CALL.","Un seul argument est utilise (RCX) ; 0x28 n'empile pas cinq arguments.","Le shadow space n'est pas un espace de sauvegarde des registres volatils par l'appelant.","C'est l'appelant qui reserve cette zone avant l'appel, pas l'espace de locales de l'appelee."]},
  {"id":"re-drapeau-teste-par-jbe","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"Drapeau testé par JBE","company":"The IDA Pro Book ch.6 — Disassembly Navigation","scenario":"cmp eax, ecx\njbe short loc_401050","question":"Sur quelle combinaison de drapeaux EFLAGS le saut JBE est-il pris ?","options":["Si CF=1 OU ZF=1 (comparaison non signée : eax <= ecx)","Si SF != OF (comparaison signée : eax <= ecx)","Uniquement si ZF=1 (les opérandes sont égales)","Si CF=1 ET ZF=0 (eax strictement inférieur à ecx)"],"answer":0,"explanation":"JBE (Jump if Below or Equal) est un saut NON signé pris quand CF=1 ou ZF=1. Le pendant signé serait JLE, qui teste ZF=1 ou SF!=OF. Distinguer JBE de JLE révèle si le code traite des entiers signés ou non signés.","tags":["eflags","x86","jumps","unsigned"],"optionNotes":["JBE (non signe) est pris si CF=1 OU ZF=1, soit eax <= ecx en non signe.","SF!=OF correspond a JL/JLE (comparaison signee), pas a JBE.","ZF=1 seul serait JE ; JBE ajoute la condition CF=1 (below).","CF=1 ET ZF=0 decrit JB (strictement inferieur), pas JBE qui inclut l'egalite."]},
  {"id":"re-l-octet-0xcc-en-memoire","type":"mcq","domain":"software","topic":"reversing","difficulty":"intermediate","title":"L'octet 0xCC en mémoire","company":"Practical Malware Analysis ch.9 — OllyDbg","question":"Un débogueur pose un breakpoint logiciel. Que fait-il concrètement en mémoire à l'adresse ciblée ?","options":["Il remplace le premier octet de l'instruction par 0xCC (INT3) et mémorise l'original","Il positionne le bit correspondant dans les registres de débogage DR0 à DR3","Il active le Trap Flag pour interrompre après chaque instruction exécutée","Il modifie la table des vecteurs d'interruption pour rerouter l'exécution"],"answer":0,"explanation":"Un breakpoint logiciel écrase le premier octet par 0xCC (opcode de INT3), déclenchant une exception à l'exécution ; le débogueur restaure l'octet original pour afficher/exécuter. Les DR0-DR3 sont des breakpoints matériels, et le Trap Flag sert au single-step.","tags":["breakpoint","int3","debugging","0xcc"],"optionNotes":["Le breakpoint logiciel ecrase le 1er octet par 0xCC (INT3) et sauvegarde l'octet original.","Positionner DR0-DR3 est un breakpoint materiel, qui n'ecrit pas 0xCC dans le code.","Le Trap Flag sert au single-step, pas a un point d'arret sur une adresse precise.","Un breakpoint ne reecrit pas l'IDT ; il patche l'instruction ciblee avec INT3."]},
  {"id":"re-limite-des-breakpoints-materiels","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"Limite des breakpoints matériels","company":"Practical Binary Analysis ch.9 — Binary Instrumentation","question":"Quelle affirmation sur les breakpoints matériels x86 est correcte ?","options":["Ils sont limités à quatre simultanés (DR0-DR3) et n'altèrent pas le code en mémoire","Ils utilisent l'opcode 0xCC mais dans une table cachée du processeur","Leur nombre est illimité car gérés entièrement par le système d'exploitation","Ils ne peuvent surveiller que l'exécution, jamais les accès en lecture/écriture"],"answer":0,"explanation":"Les registres DR0-DR3 stockent jusqu'à quatre adresses ; DR7 configure leur type (exécution, écriture, accès) et taille. N'écrivant rien dans le code, ils échappent aux contrôles d'intégrité, contrairement aux breakpoints 0xCC. Ils gèrent aussi les watchpoints data.","tags":["hardware-breakpoint","debug-registers","dr7","debugging"],"optionNotes":["Quatre max (DR0-DR3), configures par DR7 ; ils n'alterent pas le code, echappant aux checksums.","0xCC est l'opcode des breakpoints logiciels ; les materiels vivent dans les registres DR, pas dans le code.","Leur nombre est borne a 4 par le materiel (DR0-DR3), pas illimite.","Via DR7 ils surveillent aussi lecture/ecriture (watchpoints), pas seulement l'execution."]},
  {"id":"re-role-de-l-iat-dans-un-pe","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"Rôle de l'IAT dans un PE","company":"Practical Malware Analysis ch.1 — Basic Static Techniques","question":"À quoi sert l'Import Address Table (IAT) d'un exécutable PE au moment de l'exécution ?","options":["Elle contient les adresses résolues des fonctions importées, écrites par le loader","Elle liste les fonctions que le binaire exporte vers d'autres modules","Elle stocke le code de relocation appliqué quand la base de chargement change","Elle mappe les sections du fichier vers leurs adresses virtuelles en mémoire"],"answer":0,"explanation":"L'IAT est un tableau de pointeurs que le loader Windows remplit à la résolution des imports : chaque entrée reçoit l'adresse réelle de la fonction dans la DLL cible. L'EAT concerne les exports. Un IAT vide/incohérent est un indice fort de packing.","tags":["pe","iat","imports","loader"],"optionNotes":["L'IAT recoit du loader les adresses reelles des fonctions importees, une par entree.","Lister les fonctions exportees est le role de l'EAT, pas de l'IAT.","Les corrections d'adresses au changement de base relevent de .reloc, pas de l'IAT.","Le mappage sections vers VA vient de l'en-tete des sections, pas de l'IAT."]},
  {"id":"re-addressofentrypoint","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"AddressOfEntryPoint","company":"The IDA Pro Book ch.14 — PE Files","scenario":"En-tête optional : ImageBase=0x400000, AddressOfEntryPoint=0x12A0","question":"À quelle adresse virtuelle l'exécution démarre-t-elle après le chargement ?","options":["0x4012A0, soit ImageBase + AddressOfEntryPoint","0x12A0, l'AddressOfEntryPoint étant déjà une adresse virtuelle","0x400000, l'ImageBase servant toujours de point d'entrée réel","0x4012A0 seulement si la relocation est désactivée, sinon 0x12A0"],"answer":0,"explanation":"AddressOfEntryPoint est un RVA (offset relatif à ImageBase). L'adresse d'exécution est ImageBase + RVA = 0x400000 + 0x12A0 = 0x4012A0. Attention : ce point d'entrée est souvent celui du CRT/stub du packer, pas du main du programmeur.","tags":["pe","entry-point","rva","imagebase"],"optionNotes":["AddressOfEntryPoint est un RVA : VA = ImageBase + RVA = 0x400000 + 0x12A0 = 0x4012A0.","0x12A0 est un RVA (offset), pas une adresse virtuelle deja absolue.","0x400000 est la base de l'image, pas le point d'entree reel.","La relocation ne change pas la formule ImageBase+RVA ; l'EP reste 0x4012A0."]},
  {"id":"re-resolution-paresseuse-via-plt-got","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"Résolution paresseuse via PLT/GOT","company":"Practical Binary Analysis ch.2 — The ELF Format","scenario":"call printf@plt\n; PLT[n]: jmp *GOT[n]  (première fois -> résolveur)","question":"Lors du PREMIER appel à printf via la PLT, que contient l'entrée GOT correspondante ?","options":["L'adresse de l'instruction suivante dans le stub PLT, qui saute vers le résolveur dynamique","Directement l'adresse de printf dans la libc, pré-résolue au chargement","Un pointeur nul déclenchant une faute que le linker intercepte","L'adresse de _dl_runtime_resolve accompagnée de l'index de relocation"],"answer":0,"explanation":"En lazy binding, GOT[n] pointe initialement vers l'instruction suivant le jmp dans le stub PLT ; celle-ci empile l'index de relocation puis saute vers le résolveur (_dl_runtime_resolve). Après résolution, la GOT est réécrite avec l'adresse réelle : les appels suivants sautent directement. La GOT est une cible privilégiée d'écrasement.","tags":["elf","plt","got","lazy-binding"],"optionNotes":["Au 1er appel, GOT[n] renvoie vers l'instruction suivante du stub PLT, qui saute au resolveur.","L'adresse reelle de printf n'y est ecrite qu'apres la 1re resolution (lazy binding).","GOT[n] n'est pas nul : il pointe le stub PLT, il n'y a pas de faute interceptee.","_dl_runtime_resolve et l'index sont pousses par le stub, pas stockes initialement dans GOT[n]."]},
  {"id":"re-desassemblage-lineaire-piege","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"Désassemblage linéaire piégé","company":"The IDA Pro Book ch.5 — IDA Data Displays","question":"Pourquoi le désassemblage linéaire (linear sweep) échoue-t-il souvent là où le récursif (recursive descent) réussit ?","options":["Il décode les données inline (jump tables, constantes) comme du code, se désynchronisant","Il ne suit pas les appels indirects et manque donc des fonctions entières","Il ignore les sauts conditionnels et n'explore qu'un seul chemin d'exécution","Il exige des symboles de débogage pour délimiter le début des fonctions"],"answer":0,"explanation":"Le linear sweep décode octet après octet sans suivre le flot ; dès qu'il rencontre des données mêlées au code (tables de saut, bourrage) il les interprète comme instructions et se désaligne. Le recursive descent suit les branches et évite ces zones, au prix de manquer le code atteint uniquement par sauts indirects.","tags":["disassembly","linear-sweep","recursive-descent","alignment"],"optionNotes":["Le linear sweep decode les donnees inline (jump tables, bourrage) comme du code et se desaligne.","Ne pas suivre les appels indirects est une limite du recursive descent, pas du linear sweep.","Le linear sweep decode tout sequentiellement ; c'est le recursif qui suit les branches d'execution.","Le linear sweep n'exige pas de symboles ; il decode octet apres octet sans eux."]},
  {"id":"re-lecture-directe-du-peb-pour-l-anti-debug","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"Lecture directe du PEB pour l'anti-debug","company":"Practical Malware Analysis ch.16 — Anti-Debugging","scenario":"mov eax, fs:[0x30]\nmovzx eax, byte ptr [eax+2]\ntest eax, eax\njne being_debugged","question":"Quel contrôle anti-debug ce code réalise-t-il ?","options":["Il lit PEB.BeingDebugged (offset 2) directement, équivalent à IsDebuggerPresent","Il inspecte PEB.NtGlobalFlag pour détecter le tas de débogage","Il compare le PID du parent pour repérer un lancement par débogueur","Il vérifie la présence d'un handle de débogage via NtQueryInformationProcess"],"answer":0,"explanation":"fs:[0x30] pointe le PEB en x86 ; l'octet à l'offset +2 est BeingDebugged. Le lire en direct contourne un hook posé sur l'API IsDebuggerPresent. NtGlobalFlag se trouve à l'offset 0x68, ce n'est pas ce contrôle-ci.","tags":["anti-debug","peb","beingdebugged","fs"],"optionNotes":["fs:[0x30] donne le PEB ; l'octet +2 est BeingDebugged, lu en direct pour contourner le hook d'IsDebuggerPresent.","NtGlobalFlag est a l'offset 0x68 du PEB, pas +2 ; ce code lit un autre champ.","Aucune comparaison de PID parent ici ; le code lit un octet du PEB.","Le controle par NtQueryInformationProcess n'implique pas la lecture directe de fs:[0x30]+2."]},
  {"id":"re-ntglobalflag-comme-indicateur","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"NtGlobalFlag comme indicateur","company":"Practical Malware Analysis ch.16 — Anti-Debugging","scenario":"mov eax, fs:[0x30]\nmov eax, [eax+0x68]\nand eax, 0x70\njnz debugger_detected","question":"Que détecte ce fragment via le champ à l'offset 0x68 du PEB ?","options":["NtGlobalFlag portant les bits de heap de débogage (0x70) mis quand le process est créé sous débogueur","Le compteur de threads suspendus positionné par le débogueur à l'attachement","L'adresse de la structure PEB_LDR_DATA modifiée par les breakpoints","Le drapeau CheckRemoteDebuggerPresent hérité du process parent"],"answer":0,"explanation":"NtGlobalFlag (PEB+0x68) reçoit FLG_HEAP_ENABLE_TAIL_CHECK|FREE_CHECK|VALIDATE_PARAMETERS (0x70) lorsqu'un process est lancé sous débogueur. Le masque 0x70 est le test classique. C'est distinct de BeingDebugged et plus difficile à neutraliser sans patch mémoire.","tags":["anti-debug","ntglobalflag","peb","heap-flags"],"optionNotes":["PEB+0x68 = NtGlobalFlag ; les bits heap 0x70 sont mis quand le process nait sous debogueur.","Aucun compteur de threads suspendus n'est a +0x68 ; c'est NtGlobalFlag.","PEB_LDR_DATA est un pointeur distinct ; +0x68 est NtGlobalFlag et les BP ne le modifient pas.","CheckRemoteDebuggerPresent est une API, pas un champ a PEB+0x68."]},
  {"id":"re-rdtsc-comme-detecteur-de-debogage","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"RDTSC comme détecteur de débogage","company":"Practical Malware Analysis ch.16 — Anti-Debugging","scenario":"rdtsc\nmov ecx, eax\n; ... quelques instructions ...\nrdtsc\nsub eax, ecx\ncmp eax, 0x10000\nja debugger","question":"Quel principe anti-reversing exploite cette séquence ?","options":["Timing : un delta de cycles anormalement élevé trahit un pas-à-pas ou des breakpoints","Elle détecte une VM en comparant la fréquence TSC virtualisée à une valeur attendue","Elle vérifie que RDTSC n'est pas émulé en comparant EAX et EDX","Elle lit un compteur de performance pour repérer un hook sur les API de temps"],"answer":0,"explanation":"Deux RDTSC encadrent un bloc court ; sous un débogueur en single-step ou avec des breakpoints, l'exécution est ralentie et le delta explose au-delà du seuil. C'est une détection temporelle, indépendante des API de temps (donc difficile à hooker).","tags":["anti-debug","rdtsc","timing","stealth"],"optionNotes":["Deux RDTSC encadrent un bloc court : un delta enorme trahit un single-step ou des breakpoints.","Ici on mesure un delta local, pas une frequence TSC comparee pour detecter une VM.","Le test porte sur l'ecart temporel (EAX), pas sur EAX vs EDX pour detecter une emulation.","RDTSC lit le TSC directement, sans passer par des API de temps hookables."]},
  {"id":"re-signature-d-un-binaire-packe-upx","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"Signature d'un binaire packé UPX","company":"Practical Malware Analysis ch.1 — Basic Static Techniques","question":"Quels indices statiques suggèrent le plus fortement un exécutable compressé par UPX ?","options":["Sections nommées UPX0/UPX1, IAT quasi vide et forte entropie du code","Table d'exports volumineuse et nombreuses chaînes ASCII lisibles","Point d'entrée dans .text avec un CRT Microsoft standard reconnu","Table de relocation absente et horodatage de compilation récent"],"answer":0,"explanation":"UPX renomme les sections en UPX0 (vide, décompression cible) et UPX1 (données compressées), réduit l'IAT à quelques imports (LoadLibrary/GetProcAddress) et produit une entropie élevée. Beaucoup de chaînes lisibles indiquerait au contraire l'absence de packing.","tags":["packer","upx","entropy","static-analysis"],"optionNotes":["UPX0/UPX1 comme sections, IAT reduite (LoadLibrary/GetProcAddress) et forte entropie signent UPX.","Un packer reduit les chaines lisibles et n'expose pas une grosse table d'exports.","Un CRT Microsoft standard reconnu indique au contraire un binaire non packe.","Absence de .reloc et horodatage recent ne sont pas des signes specifiques d'UPX."]},
  {"id":"re-trio-d-api-de-l-injection-de-code","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"Trio d'API de l'injection de code","company":"Practical Malware Analysis ch.12 — Covert Malware Launching","scenario":"OpenProcess -> VirtualAllocEx -> WriteProcessMemory -> CreateRemoteThread","question":"Quelle technique cette séquence d'API met-elle en oeuvre ?","options":["Injection de code dans un process distant : allouer, écrire le shellcode, lancer un thread","DLL hijacking en remplaçant une bibliothèque chargée par le process cible","Hollowing consistant à démapper l'image d'origine avant de la réécrire","Hooking IAT du process cible pour rerouter ses appels système"],"answer":0,"explanation":"VirtualAllocEx réserve de la mémoire dans le process distant, WriteProcessMemory y copie le payload, CreateRemoteThread l'exécute. C'est l'injection classique. Le process hollowing ajouterait NtUnmapViewOfSection/SetThreadContext ; le DLL injection écrirait un chemin puis appellerait LoadLibrary.","tags":["injection","createremotethread","malware","process"],"optionNotes":["VirtualAllocEx/WriteProcessMemory/CreateRemoteThread : allouer, ecrire le shellcode, l'executer a distance.","Le DLL hijacking exploite l'ordre de recherche des DLL, sans WriteProcessMemory ni thread distant.","Le hollowing ajouterait NtUnmapViewOfSection/SetThreadContext, absents ici.","Le hooking d'IAT reecrit des pointeurs d'import, pas via CreateRemoteThread."]},
  {"id":"re-iat-hooking-vs-inline-hooking","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"IAT hooking vs inline hooking","company":"Practical Malware Analysis ch.12 — Covert Malware Launching","question":"Quelle différence essentielle sépare le hooking d'IAT du hooking inline (patch de la fonction) ?","options":["L'IAT hook réécrit le pointeur d'import ; l'inline hook modifie les premiers octets de la fonction cible","L'IAT hook patche le prologue de la fonction ; l'inline hook remplace une entrée de table","L'IAT hook n'affecte que les appels statiques ; l'inline hook nécessite un pilote noyau","L'IAT hook fonctionne en ring 0 uniquement ; l'inline hook reste en ring 3"],"answer":0,"explanation":"Le hook d'IAT remplace l'adresse dans la table des imports du module : seuls les appels passant par cette IAT sont détournés (les résolutions dynamiques via GetProcAddress y échappent). Le hook inline écrase les premiers octets de la fonction (souvent par un jmp), interceptant tous les appelants.","tags":["hooking","iat","inline-hook","malware"],"optionNotes":["IAT hook : reecrire le pointeur dans la table d'imports ; inline hook : patcher les 1ers octets de la fonction.","Description inversee : c'est l'inline qui patche le prologue, l'IAT qui remplace l'entree de table.","L'inline hook n'exige pas de pilote noyau ; les deux se font en ring 3.","Les deux fonctionnent en ring 3 ; l'IAT hook n'est pas cantonne au ring 0."]},
  {"id":"re-boucle-de-dechiffrement-xor","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"Boucle de déchiffrement XOR","company":"Practical Malware Analysis ch.13 — Data Encoding","scenario":"mov ecx, 0x20\nlea esi, [enc_data]\nmov al, 0x5A\ndecode:\nxor byte ptr [esi], al\ninc esi\nloop decode","question":"Que fait cette boucle et quelle en est la faiblesse pour l'analyste ?","options":["Elle déchiffre 32 octets par XOR avec la clé fixe 0x5A, trivialement réversible","Elle applique un XOR à clé roulante dérivée du compteur, plus dure à casser","Elle calcule un checksum XOR pour vérifier l'intégrité des 32 octets","Elle chiffre les données en AES-CTR avec 0x5A comme vecteur d'initialisation"],"answer":0,"explanation":"AL reste constant à 0x5A : c'est un XOR mono-octet sur 32 octets (ECX). Trivial à annuler puisque XOR est involutif et la clé fixe. Un XOR à clé roulante modifierait AL à chaque tour ; ce n'est ni un checksum ni de l'AES.","tags":["xor","string-decryption","malware","obfuscation"],"optionNotes":["AL=0x5A reste constant : XOR mono-octet sur 32 octets, involutif donc trivial a annuler.","Aucune modification d'AL dans la boucle : la cle est fixe, pas roulante.","XOR ecrit ici sur [esi] (dechiffrement en place), ce n'est pas un checksum en lecture seule.","Un simple xor byte n'est pas de l'AES-CTR ; 0x5A est une cle XOR, pas un IV."]},
  {"id":"re-semantique-d-un-gadget-rop","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"Sémantique d'un gadget ROP","company":"Practical Binary Analysis ch.5 — Basic Binary Analysis on Linux","scenario":"0x4011f7: pop rdi\n0x4011f8: ret","question":"Dans une chaîne ROP, à quoi sert précisément ce gadget ?","options":["Charger dans RDI la valeur suivante sur la pile, puis rendre la main au gadget suivant","Dépiler l'adresse de retour vers RDI pour détourner le flot d'exécution","Sauvegarder RDI sur la pile avant l'appel de la fonction cible","Aligner la pile sur 16 octets avant un appel respectant l'ABI"],"answer":0,"explanation":"pop rdi transfère le mot au sommet de la pile dans RDI, ret enchaîne sur le gadget/adresse suivant. Sur System V, RDI porte le premier argument : ce gadget sert typiquement à préparer l'argument d'un system()/execve dans une chaîne ROP.","tags":["rop","gadget","exploitation","x64"],"optionNotes":["pop rdi charge le mot au sommet de pile dans RDI, ret enchaine : prepare le 1er argument System V.","Le ret ne detourne pas RDI ; il utilise l'adresse suivante de la pile comme cible.","pop rdi lit depuis la pile vers RDI, il ne sauvegarde pas RDI sur la pile.","Ce gadget ne realigne pas la pile ; il place une valeur dans RDI."]},
  {"id":"re-vulnerabilite-dans-une-copie-de-tampon","type":"find-error","domain":"software","topic":"reversing","difficulty":"senior","title":"Vulnérabilité dans une copie de tampon","company":"Practical Binary Analysis ch.5 — Exploitation basics","language":"c","code":"#include <string.h>\n#include <stdio.h>\n\nvoid handle(const char *input) {\n    char buffer[64];\n    strcpy(buffer, input);\n    printf(\"Recu: %s\\n\", buffer);\n}\n\nint main(int argc, char **argv) {\n    if (argc > 1)\n        handle(argv[1]);\n    return 0;\n}","question":"Quelle est la vulnérabilité exploitable dans ce code ?","options":["strcpy ne borne pas la copie : un argv[1] > 63 octets déborde buffer et écrase l'adresse de retour","printf reçoit une chaîne contrôlée par l'utilisateur, créant une faille de format string","argv[1] peut être NULL et provoquer un déréférencement nul dans handle","buffer n'est pas initialisé, exposant des données résiduelles de la pile"],"answer":0,"explanation":"strcpy copie jusqu'au \\0 source sans vérifier la taille de buffer[64] : au-delà de 64 octets on écrase le canari/sauvegarde RBP/adresse de retour (stack smashing). printf reçoit ici une chaîne de format constante (%s), donc pas de format string. Correctif : strncpy/strlcpy borné.","tags":["buffer-overflow","strcpy","stack-smashing","c"],"optionNotes":["strcpy copie sans borne : un argv[1] > 63 octets deborde buffer[64] et ecrase l'adresse de retour.","printf recoit ici un format constant (%s) ; pas de format string exploitable.","Un argv[1] NULL est ecarte par argc>1 ; le vrai defaut est le debordement de pile.","buffer est ecrit par strcpy avant lecture ; le probleme est le debordement, pas des residus."]},
  {"id":"re-faille-de-chaine-de-format","type":"find-error","domain":"software","topic":"reversing","difficulty":"senior","title":"Faille de chaîne de format","company":"Practical Malware Analysis ch.11 — Malware Behavior","language":"c","code":"#include <stdio.h>\n\nvoid log_event(const char *user_msg) {\n    char line[128];\n    snprintf(line, sizeof(line), \"%s\", user_msg);\n    printf(line);\n    printf(\"\\n\");\n}","question":"Où se situe la vulnérabilité ?","options":["printf(line) traite une donnée utilisateur comme format : %n/%x permettent lecture et écriture mémoire","snprintf peut tronquer user_msg et laisser line sans terminateur nul","line est alloué sur la pile, donc printf lit de la mémoire non initialisée","Le second printf(\"\\n\") provoque un dépassement d'un octet dans line"],"answer":0,"explanation":"printf(line) utilise une chaîne contrôlée comme format string : des spécificateurs %x/%s divulguent la pile, %n y écrit. Il fallait printf(\"%s\", line). snprintf garantit ici le terminateur nul et ne déborde pas ; le vrai défaut est l'usage direct de line comme format.","tags":["format-string","printf","vulnerability","c"],"optionNotes":["printf(line) prend une donnee utilisateur comme format : %x/%s divulguent, %n ecrit en memoire.","snprintf(...,sizeof) garantit ici la troncature ET le terminateur nul.","line est rempli par snprintf ; le defaut est son usage comme format, pas une lecture non initialisee.","printf(\"\\n\") ecrit une constante et ne touche pas line ; aucun depassement."]},
  {"id":"re-signatures-flirt","type":"mcq","domain":"software","topic":"reversing","difficulty":"intermediate","title":"Signatures FLIRT","company":"The IDA Pro Book ch.12 — Library Recognition Using FLIRT","question":"À quoi servent les signatures FLIRT dans IDA ?","options":["Identifier et nommer automatiquement des fonctions de bibliothèque statiquement liées","Décompiler le code machine en pseudo-C via le microcode Hex-Rays","Détecter les fonctions chiffrées par un packer avant décompression","Reconstruire l'IAT d'un binaire dont les imports ont été effacés"],"answer":0,"explanation":"FLIRT (Fast Library Identification and Recognition Technology) compare des motifs d'octets aux signatures de fonctions de librairies (CRT, MFC...) statiquement liées, pour les nommer automatiquement et éviter à l'analyste de reverser du code standard. Ce n'est ni de la décompilation ni du dépackage.","tags":["ida","flirt","library-recognition","static-analysis"],"optionNotes":["FLIRT reconnait par motifs d'octets les fonctions de librairies liees statiquement et les nomme.","La decompilation en pseudo-C est le role de Hex-Rays, pas de FLIRT.","FLIRT n'attaque pas le packing ; il identifie du code de bibliotheque connu.","Reconstruire l'IAT n'est pas la fonction de FLIRT (reconnaissance de librairies)."]},
  {"id":"re-p-code-et-microcode","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"P-code et microcode","company":"The Ghidra Book ch.18 — The P-Code Reference","question":"Quel est le rôle du P-code dans l'architecture d'analyse de Ghidra ?","options":["Une représentation intermédiaire indépendante de l'ISA sur laquelle s'appuient l'analyse et la décompilation","Un langage d'extension permettant de scripter des transformations sur le désassemblage","Le bytecode exécuté par l'émulateur intégré pour l'analyse dynamique uniquement","Le format de stockage compressé des projets Ghidra multi-utilisateurs"],"answer":0,"explanation":"Le P-code est la représentation intermédiaire (IR) de Ghidra : chaque instruction machine est traduite en opérations P-code atomiques, ce qui rend l'analyse (data-flow, décompilation) largement indépendante de l'architecture cible. Le microcode Hex-Rays joue un rôle analogue dans IDA.","tags":["ghidra","p-code","intermediate-representation","decompilation"],"optionNotes":["Le P-code est l'IR de Ghidra : chaque instruction devient des operations atomiques, independantes de l'ISA.","Scripter Ghidra passe par l'API Java/Python, pas par le P-code lui-meme.","Le P-code sert a l'analyse statique et a la decompilation, pas uniquement a l'emulation dynamique.","Le P-code n'est pas un format de stockage de projet, mais une representation intermediaire."]},
  {"id":"re-reconnaitre-un-epilogue","type":"mcq","domain":"software","topic":"reversing","difficulty":"intermediate","title":"Reconnaître un épilogue","company":"Practical Binary Analysis ch.1 — Anatomy of a Binary","scenario":"mov rsp, rbp\npop rbp\nret","question":"Que réalise ce fragment et par quelle instruction unique peut-on parfois le remplacer ?","options":["Un épilogue restaurant la pile et RBP puis retournant ; équivalent à leave suivi de ret","Un prologue réservant l'espace des locales ; équivalent à enter","Un nettoyage stdcall dépilant les arguments ; équivalent à ret N","Une sauvegarde de contexte avant un appel ; équivalent à pushad"],"answer":0,"explanation":"mov rsp,rbp ; pop rbp défont le cadre de pile, ret revient à l'appelant : c'est l'épilogue. L'instruction leave réalise exactement mov rsp,rbp ; pop rbp. enter est son pendant pour le prologue.","tags":["epilogue","leave","stack-frame","x64"],"optionNotes":["mov rsp,rbp/pop rbp/ret defont le cadre : epilogue, dont leave est l'equivalent des deux premieres.","Un prologue installe le cadre (enter) ; ici on le demantele.","Un nettoyage stdcall (ret N) depile des arguments ; ici mov rsp,rbp restaure la pile du cadre.","pushad sauve les registres ; ce fragment restaure la pile et retourne."]},
  {"id":"re-passage-d-arguments-en-fastcall","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"Passage d'arguments en fastcall","company":"Reversing: Secrets of Reverse Engineering ch.5","question":"Sous la convention __fastcall (x86, Microsoft), comment les deux premiers arguments entiers sont-ils transmis ?","options":["Dans ECX et EDX ; les arguments restants sont empilés de droite à gauche","Dans EAX et EDX ; le nettoyage de la pile incombe à l'appelant","Dans ECX et EDX ; l'appelant nettoie systématiquement les arguments empilés","Entièrement sur la pile, ECX servant uniquement au pointeur this"],"answer":0,"explanation":"__fastcall place les deux premiers arguments intégraux/pointeurs dans ECX et EDX, le reste sur la pile de droite à gauche ; comme stdcall, c'est l'appelé qui nettoie (ret N). ECX seul pour this correspond à thiscall, une convention distincte.","tags":["fastcall","calling-convention","x86","registers"],"optionNotes":["__fastcall (MS) : 1er et 2e args dans ECX et EDX, le reste empile de droite a gauche.","Ce sont ECX/EDX (pas EAX/EDX), et l'appele nettoie comme stdcall.","Comme stdcall, c'est l'appele (ret N) qui nettoie, pas systematiquement l'appelant.","ECX seul pour this decrit thiscall ; fastcall utilise ECX ET EDX pour les args."]},
  {"id":"re-anti-debug-par-exception-seh","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"Anti-debug par exception SEH","company":"Practical Malware Analysis ch.16 — Anti-Debugging","scenario":"push offset handler\npush fs:[0]\nmov fs:[0], esp\nint 3\n; suite normale si handler a repris la main","question":"Comment ce code détecte-t-il un débogueur via une exception ?","options":["Sans débogueur, INT3 lève une exception que le handler SEH intercepte ; un débogueur avale l'exception et rompt le flot attendu","Il installe un hook SEH qui compte les breakpoints matériels posés par le débogueur","INT3 force le débogueur à afficher son adresse, révélée par le handler","Le handler SEH lit BeingDebugged et déclenche INT3 seulement si vrai"],"answer":0,"explanation":"Le code enregistre un gestionnaire SEH puis exécute INT3. En exécution normale, l'exception BREAKPOINT est délivrée au handler qui reprend l'exécution ; sous un débogueur, celui-ci intercepte l'exception (ne la passe pas au programme), donc le handler n'est pas appelé : la divergence de comportement trahit le débogueur.","tags":["anti-debug","seh","int3","exceptions"],"optionNotes":["Sans debogueur, INT3 leve l'exception geree par le handler SEH ; un debogueur l'avale et le handler n'est pas appele.","Le code ne compte pas de breakpoints materiels ; il exploite la gestion de l'exception INT3.","INT3 ne 'revele' pas l'adresse du debogueur ; c'est la deviation de flot qui trahit.","Le handler ne lit pas BeingDebugged ; la detection vient de qui gere l'exception."]},
  {"id":"re-int-2d-en-anti-reversing","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"INT 2D en anti-reversing","company":"Practical Malware Analysis ch.16 — Anti-Debugging","question":"Pourquoi l'instruction INT 2D est-elle utilisée comme technique anti-debug ?","options":["Sous débogueur, elle modifie le traitement de l'exception et peut faire sauter un octet, désalignant la suite","Elle bascule le processeur en ring 0 pour lire les registres de débogage","Elle vide le TLB, invalidant les breakpoints matériels du débogueur","Elle génère systématiquement une faute que seul un débogueur peut résoudre"],"answer":0,"explanation":"INT 2D est utilisé par le noyau pour les points d'arrêt de débogage kernel. En user-land sous débogueur, son traitement diffère : selon le débogueur, l'octet suivant l'INT 2D est considéré consommé (EIP avancé), désynchronisant l'analyse ; hors débogueur elle lève simplement une exception. Cette divergence sert de détecteur.","tags":["anti-debug","int2d","exceptions","stealth"],"optionNotes":["Sous debogueur, INT 2D change le traitement de l'exception et peut faire sauter l'octet suivant, desalignant.","INT 2D ne fait pas passer le code utilisateur en ring 0 pour lire les DR.","INT 2D ne vide pas le TLB ni n'invalide les breakpoints materiels.","Hors debogueur INT 2D leve simplement une exception ; ce n'est pas 'resoluble' par le seul debogueur."]},
  {"id":"re-detection-de-vm-par-cpuid","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"Détection de VM par CPUID","company":"Practical Malware Analysis ch.17 — Anti-Virtual Machine Techniques","scenario":"mov eax, 1\ncpuid\nbt ecx, 31\njc inside_vm","question":"Que teste ce fragment via CPUID feuille 1 ?","options":["Le bit 31 d'ECX (hypervisor present) mis par la plupart des hyperviseurs","Le bit 31 d'ECX indiquant le support des instructions AVX-512","La présence des extensions VT-x/AMD-V exposées au système invité","Le numéro de série du processeur pour repérer un environnement cloné"],"answer":0,"explanation":"CPUID(EAX=1) renvoie dans ECX un bit 31 dit 'hypervisor present', positionné par la plupart des hyperviseurs (VMware, KVM, Hyper-V). bt/jc le teste. Ce bit est purement conventionnel et facilement masquable, mais reste un anti-VM courant. Il ne s'agit pas d'AVX-512 (bit différent, autre feuille).","tags":["anti-vm","cpuid","hypervisor","malware"],"optionNotes":["CPUID(EAX=1) : le bit 31 d'ECX 'hypervisor present' est pose par la plupart des hyperviseurs.","Le support AVX-512 se lit sur d'autres bits/feuilles, pas au bit 31 d'ECX feuille 1.","Le bit 31 est une convention 'hypervisor present', pas l'exposition de VT-x/AMD-V a l'invite.","CPUID feuille 1 ne renvoie pas de numero de serie ; le test porte sur le bit hypervisor."]},
  {"id":"re-adressage-rip-relatif","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"Adressage RIP-relatif","company":"Practical Binary Analysis ch.2 — The ELF Format","scenario":"lea rax, [rip + 0x2ed5]\nmov rdi, rax","question":"Pourquoi le code x64 moderne privilégie-t-il cet adressage relatif à RIP ?","options":["Il produit du code indépendant de la position (PIE), l'adresse étant calculée relativement à RIP","Il réduit la taille de l'instruction en évitant un déplacement 64 bits absolu","Il empêche la relocation à la charge, l'adresse étant figée à la compilation","Il contourne le NX bit en calculant les adresses de données à l'exécution"],"answer":0,"explanation":"lea [rip+disp] calcule une adresse relative au compteur ordinal courant, permettant du code position-independent (PIE/ASLR) sans table de relocation : où que l'image soit chargée, l'offset reste valide. Ce n'est pas lié au NX bit, et cela facilite au contraire l'ASLR.","tags":["x64","rip-relative","pie","pic"],"optionNotes":["lea [rip+disp] calcule une adresse relative au RIP : code position-independent (PIE/ASLR) sans .reloc.","L'interet n'est pas la taille : c'est l'independance a la position de chargement.","Au contraire, le RIP-relatif evite les relocations en s'adaptant a toute base de chargement.","Le RIP-relatif ne contourne pas le NX ; il facilite l'ASLR."]},
  {"id":"re-idiome-test-eax-eax","type":"mcq","domain":"software","topic":"reversing","difficulty":"intermediate","title":"Idiome test eax, eax","company":"The IDA Pro Book ch.6 — Disassembly Navigation","scenario":"call GetSomething\ntest eax, eax\njz error","question":"Que vérifie l'idiome test eax, eax suivi de jz ?","options":["Si EAX vaut zéro : le AND logique met ZF=1 quand EAX est nul, sans modifier EAX","Si EAX est négatif : test positionne SF selon le bit de signe d'EAX","Si EAX a changé depuis le CALL en comparant à sa valeur d'origine","Si EAX est impair : test isole le bit de poids faible dans ZF"],"answer":0,"explanation":"test eax,eax effectue un ET logique d'EAX avec lui-même : le résultat est nul ssi EAX est nul, mettant alors ZF=1 (jz pris). C'est l'idiome compilateur pour comparer à zéro (plus court que cmp eax,0) sans altérer EAX. SF/PF sont aussi mis à jour mais l'usage vise ZF.","tags":["idiom","test","eflags","x86"],"optionNotes":["test eax,eax fait un ET logique : ZF=1 ssi EAX=0, sans modifier EAX ; jz saute si nul.","Le negatif se lirait sur SF (js), pas via jz qui teste ZF.","test compare EAX a lui-meme, pas a une valeur d'avant le CALL.","test eax,eax teste la nullite globale, pas la parite (qui isolerait le bit 0)."]},
  {"id":"re-movzx-contre-movsx","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"movzx contre movsx","company":"Practical Binary Analysis ch.1 — Anatomy of a Binary","scenario":"movsx eax, byte ptr [esi]\n; puis plus loin\nmovzx edx, byte ptr [edi]","question":"Quelle différence sémantique distingue ces deux instructions et qu'en déduit l'analyste ?","options":["movsx étend le signe (probable char signé), movzx complète par des zéros (probable unsigned char)","movsx complète par des zéros, movzx recopie le bit de signe dans les bits hauts","Les deux étendent le signe ; seule la taille du registre destination diffère","movzx préserve les bits hauts d'EDX, movsx les remet à zéro"],"answer":0,"explanation":"movsx (sign-extend) réplique le bit de poids fort : le compilateur l'émet pour un type signé (char/short). movzx (zero-extend) met des zéros en haut : type non signé. Repérer lequel est utilisé aide à retrouver le typage signé/non signé des variables sources.","tags":["movzx","movsx","sign-extension","types"],"optionNotes":["movsx etend le signe (source signee, char) ; movzx complete par des zeros (unsigned char).","Description inversee : movsx recopie le bit de signe, movzx met des zeros.","movzx n'etend PAS le signe : il met des zeros ; seul movsx propage le signe.","Les deux ecrivent tout le registre destination ; movzx met des zeros en haut, pas movsx."]},
  {"id":"re-lea-detourne-en-calcul","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"LEA détourné en calcul","company":"Reversing: Secrets of Reverse Engineering ch.2","scenario":"lea eax, [eax + eax*4]\nshl eax, 1","question":"Que calcule cette paire d'instructions, sans accès mémoire ?","options":["eax = eax * 10 : lea fait eax*5 puis shl double le résultat","eax = eax + 5 puis décale, soit un adressage de tableau d'entiers","eax = adresse de l'élément d'indice eax dans un tableau de 4 octets","eax = eax * 4 : lea additionne quatre fois eax via le facteur d'échelle"],"answer":0,"explanation":"lea [eax+eax*4] calcule eax*5 (pas d'accès mémoire : lea ne fait que l'arithmétique d'adresse), puis shl eax,1 multiplie par 2 : total eax*10. Les compilateurs exploitent lea pour des multiplications par constantes sans passer par mul.","tags":["lea","arithmetic","optimization","x86"],"optionNotes":["lea [eax+eax*4] fait eax*5 (arithmetique seule), shl eax,1 double : total eax*10.","lea calcule eax*5 (facteur 4 + eax), pas eax+5.","lea ici ne lit aucune memoire : c'est un calcul, pas un acces a un element de tableau.","Le facteur *4 plus eax donne eax*5, pas eax*4."]},
  {"id":"re-section-rwx-suspecte","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"Section RWX suspecte","company":"Practical Malware Analysis ch.1 — Basic Static Techniques","question":"Une section PE dont les Characteristics portent à la fois MEM_WRITE et MEM_EXECUTE attire l'attention. Pourquoi ?","options":["Une section à la fois inscriptible et exécutable permet un code auto-modifiant ou dépacké à l'exécution","Cela indique toujours une corruption de l'en-tête PE empêchant le chargement","Une telle section est réservée aux pilotes noyau et jamais aux exécutables user-land","C'est la configuration normale de .text, requise pour l'exécution du code"],"answer":0,"explanation":"Le code légitime réside en sections exécutables mais en lecture seule (.text = R+X) ; les données sont R+W non exécutables. Une section W+X permet d'écrire puis d'exécuter du code, typique des packers/décrypteurs/shellcode auto-modifiants. C'est un fort signal d'analyse, pas un état normal.","tags":["pe","sections","rwx","packer"],"optionNotes":["Une section W+X permet d'ecrire puis executer : code auto-modifiant ou depacke, signal fort.","Une section W+X se charge normalement ; ce n'est pas une corruption d'en-tete.","Les executables user-land peuvent avoir des sections W+X (packers) ; pas reserve au noyau.",".text normale est R+X (non inscriptible) ; W+X n'est pas l'etat standard."]},
  {"id":"re-persistance-par-cle-run","type":"mcq","domain":"software","topic":"reversing","difficulty":"intermediate","title":"Persistance par clé Run","company":"Practical Malware Analysis ch.11 — Malware Behavior","scenario":"Le malware écrit une valeur sous HKCU\\Software\\Microsoft\\Windows\\CurrentVersion\\Run","question":"Quel objectif ce comportement sert-il ?","options":["La persistance : le programme référencé sera relancé à chaque ouverture de session utilisateur","L'escalade de privilèges vers SYSTEM en détournant un service Windows","La communication C2 en encodant l'adresse du serveur dans le registre","Le contournement de l'UAC en désactivant les invites d'élévation"],"answer":0,"explanation":"La clé Run (HKCU ou HKLM) liste les programmes démarrés à l'ouverture de session : y inscrire son chemin est un mécanisme de persistance classique. HKCU ne confère aucune élévation de privilège (c'est justement pourquoi il ne requiert pas les droits admin).","tags":["persistence","registry","run-key","malware"],"optionNotes":["La cle Run relance le programme a chaque ouverture de session : mecanisme de persistance.","HKCU\\...\\Run ne confere aucune elevation vers SYSTEM.","La cle Run sert a l'auto-demarrage, pas a encoder une adresse C2.","Ecrire dans Run ne desactive pas l'UAC ni ses invites d'elevation."]},
  {"id":"re-reconnaitre-un-beacon-c2","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"Reconnaître un beacon C2","company":"Practical Malware Analysis ch.14 — Malware-Focused Network Signatures","question":"Quel motif réseau caractérise le mieux le beaconing d'un implant vers son C2 ?","options":["Des requêtes sortantes périodiques à intervalles réguliers (avec jitter) vers un même hôte","Un flux entrant massif ouvrant un port en écoute sur la machine infectée","Des scans de ports internes cherchant d'autres machines à compromettre","Un transfert unique et volumineux de données chiffrées vers un serveur FTP"],"answer":0,"explanation":"Le beaconing est le check-in régulier de l'implant vers le C2 pour recevoir des ordres : petites requêtes sortantes à cadence fixe, souvent avec du jitter pour brouiller la détection. Un port en écoute évoque une backdoor passive ; le scan interne relève du mouvement latéral.","tags":["c2","beaconing","network","malware"],"optionNotes":["Le beaconing : petites requetes sortantes periodiques (avec jitter) vers un meme hote C2.","Un port en ecoute entrant evoque une backdoor passive, pas un beacon sortant.","Scanner des ports internes releve du mouvement lateral, pas du beaconing.","Un transfert unique et massif est de l'exfiltration, pas le check-in regulier d'un beacon."]},
  {"id":"re-binaire-strippe","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"Binaire strippé","company":"Practical Binary Analysis ch.6 — Disassembly and Analysis","question":"Quel est l'effet principal du stripping (strip) sur un ELF pour l'analyste ?","options":["Il supprime la table de symboles .symtab, effaçant les noms de fonctions et variables locales","Il chiffre la section .text, empêchant le désassemblage sans clé","Il retire la section .dynamic, rendant les imports dynamiques introuvables","Il efface la table des relocations, bloquant le chargement du binaire"],"answer":0,"explanation":"strip retire .symtab et .strtab (symboles de débogage/locaux), donc les noms de fonctions internes disparaissent — l'analyste ne voit plus que sub_XXXX. Les symboles dynamiques (.dynsym) restent nécessaires au linking et subsistent, tout comme .dynamic et les relocations.","tags":["stripping","symbols","elf","static-analysis"],"optionNotes":["strip retire .symtab/.strtab : les noms de fonctions internes disparaissent (sub_XXXX).","strip ne chiffre pas .text ; le desassemblage reste possible, seuls les noms partent.",".dynamic reste (necessaire au linking dynamique) ; strip ne l'enleve pas.","Les relocations restent ; le binaire se charge toujours apres strip."]},
  {"id":"re-anti-debug-par-somme-de-controle-du-code","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"Anti-debug par somme de contrôle du code","company":"Practical Malware Analysis ch.16 — Anti-Debugging","scenario":"La fonction calcule un CRC sur ses propres octets et le compare à une valeur codée en dur.","question":"Contre quelle technique de débogage ce contrôle d'intégrité protège-t-il ?","options":["Les breakpoints logiciels : l'octet 0xCC inséré modifie le code et fausse la somme","Les breakpoints matériels, qui réécrivent le premier octet de la fonction","Le single-step, en mesurant le temps de calcul du CRC","L'attachement d'un débogueur, détecté via le PEB pendant le calcul"],"answer":0,"explanation":"Un breakpoint logiciel remplace un octet du code par 0xCC : le CRC calculé sur la zone diffère alors de la valeur attendue, révélant la présence du breakpoint. Les breakpoints matériels (DR0-DR3), n'altérant pas le code, échappent justement à ce contrôle d'intégrité.","tags":["anti-debug","checksum","int3","self-checking"],"optionNotes":["Un breakpoint logiciel insere 0xCC dans le code, ce qui fausse le CRC et le trahit.","Les breakpoints materiels n'ecrivent rien dans le code : le CRC ne les voit pas.","Un CRC compare des octets, il ne mesure pas le temps du single-step.","Ce controle vise l'alteration du code (0xCC), pas la detection via le PEB."]},
  {"id":"re-trap-flag-et-single-step","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"Trap Flag et single-step","company":"The IDA Pro Book ch.24 — The IDA Debugger","question":"Comment un débogueur réalise-t-il l'exécution pas-à-pas (single-step) au niveau processeur ?","options":["Il positionne le Trap Flag (TF) dans EFLAGS : le CPU lève une exception après chaque instruction","Il insère un 0xCC après chaque instruction puis le retire une fois atteint","Il configure DR7 pour interrompre à chaque changement de RIP","Il abaisse la fréquence d'horloge pour intercepter chaque cycle d'exécution"],"answer":0,"explanation":"Quand TF=1 dans EFLAGS, le processeur génère une exception de débogage (#DB) après l'exécution de chaque instruction, donnant la main au débogueur : c'est le mécanisme du single-step. Un malware peut d'ailleurs détecter/manipuler TF pour contrer le pas-à-pas.","tags":["single-step","trap-flag","eflags","debugging"],"optionNotes":["Le debogueur met TF=1 : le CPU leve une exception #DB apres chaque instruction (single-step).","Inserer un 0xCC par instruction est lourd et faux ; le single-step utilise TF.","DR7 sert aux breakpoints materiels sur adresses, pas au pas-a-pas generalise.","La frequence d'horloge n'a rien a voir ; le mecanisme est le Trap Flag."]},
  {"id":"re-decompilation-vs-desassemblage","type":"mcq","domain":"software","topic":"reversing","difficulty":"intermediate","title":"Décompilation vs désassemblage","company":"The Ghidra Book ch.19 — The Decompiler","question":"Quelle affirmation distingue correctement décompilation et désassemblage ?","options":["Le désassemblage produit du langage machine lisible ; la décompilation reconstruit un pseudo-code de plus haut niveau","La décompilation traduit octet à octet en instructions ; le désassemblage regroupe en fonctions","Le désassemblage nécessite les symboles de débogage ; la décompilation s'en passe","La décompilation restitue exactement le code source original, commentaires compris"],"answer":0,"explanation":"Le désassemblage convertit les octets en instructions assembleur (1:1). La décompilation va plus loin en reconstruisant un pseudo-code de type C (structures de contrôle, variables) à partir de l'IR — mais approximatif : ni noms d'origine, ni commentaires, reconstruction faillible.","tags":["decompilation","disassembly","ghidra","concepts"],"optionNotes":["Desassemblage : octets vers assembleur (1:1). Decompilation : reconstruire un pseudo-code de plus haut niveau.","Description inversee : le desassemblage traduit 1:1, la decompilation monte en abstraction.","Le desassemblage ne necessite pas de symboles ; il decode les octets bruts.","La decompilation est approximative : ni noms d'origine, ni commentaires restitues."]},
  {"id":"re-patcher-un-saut-conditionnel","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"Patcher un saut conditionnel","company":"Practical Malware Analysis ch.9 — OllyDbg","scenario":"Un contrôle de licence fait : test eax, eax ; jz bad_license (opcode 74 12). On veut forcer le chemin 'valide'.","question":"Quel patch d'octet(s) neutralise le contrôle le plus proprement ?","options":["Remplacer 74 12 par 90 90 (deux NOP) : le saut conditionnel vers bad_license n'est jamais pris et l'exécution tombe systématiquement dans le chemin valide","Remplacer 74 (JZ) par EB (JMP court) : le saut deviendrait inconditionnel vers bad_license, forçant justement le mauvais chemin","Inverser en JNZ (opcode 75) : le saut vers bad_license serait pris dès que eax != 0, sans garantir le chemin valide","Remplacer test eax, eax par xor eax, eax : ZF serait forcé à 1, rendant le saut vers bad_license systématique"],"answer":0,"explanation":"jz bad_license saute vers l'échec quand ZF=1 (eax==0) ; l'exécution en séquence (fall-through) mène au chemin valide. Pour toujours emprunter ce chemin, il faut neutraliser le saut conditionnel : remplacer les deux octets 74 12 par 90 90 (NOP NOP), de sorte que le saut ne soit jamais pris. Passer 74 en EB (JMP inconditionnel) sauterait au contraire toujours vers bad_license ; JNZ (75) et xor eax,eax mènent aussi au mauvais chemin.","tags":["patching","jz","jmp","binary-patching"],"optionNotes":["74 12 devient 90 90 (NOP NOP) : le saut vers bad_license n'est jamais pris, le fall-through mene au chemin valide.","74 vers EB rend le saut inconditionnel vers bad_license : on force le MAUVAIS chemin.","JNZ (75) sauterait vers bad_license des eax!=0, sans garantir le chemin valide.","xor eax,eax force ZF=1 donc jz est pris vers bad_license : mauvais chemin."]},
  {"id":"re-bug-dans-un-dechiffreur-xor-python","type":"find-error","domain":"software","topic":"reversing","difficulty":"senior","title":"Bug dans un déchiffreur XOR Python","company":"Practical Malware Analysis ch.13 — Data Encoding","language":"python","code":"def xor_decrypt(data: bytes, key: bytes) -> bytes:\n    out = bytearray()\n    for i in range(len(data)):\n        out.append(data[i] ^ key[i])\n    return bytes(out)\n\n# key est plus courte que data (clé roulante attendue)\nplaintext = xor_decrypt(ciphertext, b\"S3cr3t\")","question":"Pourquoi ce déchiffrement de chaîne à clé roulante échoue-t-il ?","options":["key[i] lève un IndexError dès que i dépasse la longueur de la clé ; il faut key[i % len(key)]","data[i] retourne un int alors que key[i] retourne des bytes, l'XOR est invalide","bytearray.append attend un octet mais reçoit le résultat d'un XOR sur des entiers","bytes(out) reconvertit mal les valeurs supérieures à 127 en UTF-8"],"answer":0,"explanation":"Pour une clé plus courte que les données, il faut la faire cycler : key[i % len(key)]. Tel quel, dès i >= len(key), key[i] déclenche IndexError. En Python 3, indexer des bytes donne bien un int (donc l'XOR int^int est valide et append reçoit un int correct) : le seul vrai bug est l'absence du modulo.","tags":["python","xor","rolling-key","deobfuscation"],"optionNotes":["Cle plus courte que data : sans key[i % len(key)], key[i] leve IndexError des i >= len(cle).","En Python 3, indexer des bytes renvoie un int : l'XOR int^int est valide.","append recoit bien un int (resultat de l'XOR), pas un type incompatible.","bytes(out) reconstruit fidelement les octets 0-255 ; aucune conversion UTF-8 n'intervient."]},
  {"id":"re-consequence-d-un-call-pop","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"Conséquence d'un call/pop","company":"Practical Malware Analysis ch.19 — Shellcode Analysis","scenario":"call next\nnext:\npop ebx","question":"Quel objectif ce motif call/pop remplit-il, typique du shellcode ?","options":["Obtenir dans EBX l'adresse absolue de 'next', réalisant un get-EIP pour du code position-independent","Sauvegarder l'adresse de retour de l'appelant pour la restaurer plus tard","Créer un cadre de pile factice afin de masquer la trace d'appel","Aligner la pile sur 16 octets avant l'exécution du payload principal"],"answer":0,"explanation":"call empile l'adresse de l'instruction suivante (label next) ; pop ebx la récupère. EBX contient alors l'adresse absolue courante en mémoire, permettant au shellcode de référencer ses données/chaînes en relatif sans adresses codées en dur : c'est l'idiome get-EIP/get-PC.","tags":["shellcode","get-eip","position-independent","call-pop"],"optionNotes":["call empile l'adresse de 'next', pop ebx la recupere : get-EIP pour du code position-independent.","Le but n'est pas de sauvegarder l'adresse de retour de l'appelant, mais d'obtenir l'adresse courante.","Aucun cadre de pile factice ici : on recupere juste l'adresse dans EBX.","Ce motif n'aligne pas la pile ; il fournit l'adresse courante au shellcode."]},
  {"id":"re-ordre-d-empilement-cdecl","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"Ordre d'empilement cdecl","company":"Reversing: Secrets of Reverse Engineering ch.5","scenario":"push 3\npush 2\npush 1\ncall func\nadd esp, 0Ch","question":"Que révèlent l'ordre des push et le add esp,0Ch après le CALL ?","options":["Convention cdecl : arguments empilés de droite à gauche (1,2,3), appelant nettoyant 12 octets","Convention stdcall : l'appelant nettoie exceptionnellement car func est variadique","Les arguments sont passés de gauche à droite, func recevant 3 comme premier paramètre","Convention fastcall dégradée où seuls les arguments au-delà du troisième sont empilés"],"answer":0,"explanation":"Les push 3,2,1 puis add esp,0Ch (12 octets) montrent un empilement de droite à gauche (le premier argument, 1, est poussé en dernier donc au sommet) et un nettoyage par l'appelant : c'est cdecl. stdcall ferait nettoyer l'appelé via ret N, sans add esp visible.","tags":["cdecl","calling-convention","stack-cleanup","x86"],"optionNotes":["push 3,2,1 (droite a gauche) puis add esp,0Ch : l'appelant nettoie 12 octets, c'est cdecl.","En stdcall l'appele nettoie (ret N) ; l'add esp visible exclut stdcall, variadique ou non.","L'empilement est de droite a gauche : 1 (pousse en dernier) est le 1er argument.","fastcall passerait les 1ers args en ECX/EDX ; ici les trois sont empiles, c'est cdecl."]},
  {"id":"re-resolution-dynamique-d-api-furtive","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"Résolution dynamique d'API furtive","company":"Practical Malware Analysis ch.7 — Analyzing Malicious Windows Programs","scenario":"Le binaire n'importe que LoadLibraryA et GetProcAddress ; les autres API sont résolues à l'exécution à partir de chaînes déchiffrées.","question":"Quel est l'intérêt de cette technique pour le malware ?","options":["Masquer ses capacités à l'analyse statique : l'IAT ne révèle plus les API réellement utilisées","Contourner l'ASLR en recalculant les adresses des DLL à chaque lancement","Éviter les breakpoints matériels sur les fonctions importées","Réduire la taille du binaire en supprimant la table des imports"],"answer":0,"explanation":"En ne laissant dans l'IAT que LoadLibrary/GetProcAddress et en résolvant dynamiquement le reste depuis des chaînes (souvent chiffrées), le malware prive l'analyste statique de la liste des API sensibles (réseau, injection, crypto). Cela ne concerne ni l'ASLR ni les breakpoints ; il faut de l'analyse dynamique pour lever le voile.","tags":["dynamic-resolution","getprocaddress","iat","anti-static"],"optionNotes":["IAT limitee a LoadLibrary/GetProcAddress : les API sensibles n'apparaissent plus a l'analyse statique.","La resolution dynamique ne contourne pas l'ASLR (geree par le loader/relocations).","Elle n'a rien a voir avec les breakpoints materiels sur les imports.","Le but est la furtivite, pas la reduction de taille du binaire."]},
  {"id":"re-off-by-one-dans-une-lecture-d-en-tete","type":"find-error","domain":"software","topic":"reversing","difficulty":"senior","title":"Off-by-one dans une lecture d'en-tête","company":"Practical Binary Analysis ch.5 — Parsing headers","language":"c","code":"#include <stdint.h>\n#include <string.h>\n\nint copy_name(const uint8_t *record, char *dst) {\n    uint8_t len = record[0];      // longueur annoncee\n    char name[16];\n    memcpy(name, record + 1, len);\n    name[len] = '\\0';\n    strcpy(dst, name);\n    return 0;\n}","question":"Quelle vulnérabilité affecte cette lecture de champ à longueur préfixée ?","options":["len (jusqu'à 255) n'est pas borné à sizeof(name), donc memcpy et name[len] débordent le tampon de 16 octets","record peut être NULL, provoquant un déréférencement nul dès record[0]","memcpy avec len=0 laisse name non terminé, corrompant strcpy","dst n'est pas alloué par l'appelant, ce qui rend strcpy indéfini par principe"],"answer":0,"explanation":"len provient de la donnée (0-255) et n'est jamais comparé à sizeof(name)=16 : memcpy(name, ..., len) et l'écriture name[len]='\\0' débordent la pile dès len>=16. Il faut valider len < sizeof(name) avant toute copie. Un attaquant contrôlant record[0] déclenche un stack overflow classique de parseur.","tags":["off-by-one","memcpy","parsing","c"],"optionNotes":["len (0-255) n'est jamais borne a sizeof(name)=16 : memcpy et name[len] debordent la pile.","record peut etre non-NULL et declencher quand meme le debordement ; le NULL n'est pas le defaut ici.","len=0 laisse name[0]='\\0' (termine) ; le vrai bug est len non borne, pas la terminaison.","Le prototype suppose dst valide ; le defaut reel est le debordement de name par len non verifie."]},
  {"id":"re-detection-d-un-point-d-arret-materiel-pa","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"Détection d'un point d'arrêt matériel par le malware","company":"Practical Malware Analysis ch.16 — Anti-Debugging","question":"Comment un programme en user-land peut-il détecter la présence de breakpoints matériels posés contre lui ?","options":["En inspectant les registres DR0-DR7 via GetThreadContext/le CONTEXT d'une exception","En calculant un CRC de son propre code pour repérer les octets 0xCC insérés","En lisant PEB.BeingDebugged qui reflète l'usage des registres de débogage","En mesurant le temps entre deux RDTSC autour de la fonction protégée"],"answer":0,"explanation":"Les breakpoints matériels vivent dans DR0-DR3 (adresses) et DR7 (contrôle). Un thread peut lire ces registres via GetThreadContext (ou le CONTEXT reçu dans un gestionnaire d'exception) : des DR non nuls trahissent des breakpoints matériels. Le CRC détecte les 0xCC logiciels, pas les hardware ; BeingDebugged ne reflète pas les DR.","tags":["anti-debug","hardware-breakpoint","debug-registers","getthreadcontext"],"optionNotes":["Lire DR0-DR7 via GetThreadContext (ou le CONTEXT d'une exception) : des DR non nuls trahissent les BP materiels.","Un CRC repere les 0xCC logiciels, pas les breakpoints materiels (qui n'alterent pas le code).","BeingDebugged ne reflete pas l'etat des registres DR.","Le timing RDTSC detecte un ralentissement, pas specifiquement des breakpoints materiels."]},
  {"id":"re-trouver-l-oep-apres-depackage","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"Trouver l'OEP après dépackage","company":"Practical Malware Analysis ch.18 — Packers and Unpacking","question":"Lors du dépackage manuel d'un binaire UPX, quel indice signale le mieux l'atteinte de l'Original Entry Point (OEP) ?","options":["Un saut lointain (souvent après un popad) quittant le stub vers une zone jusque-là vide, désormais remplie de code","Le premier appel à GetProcAddress effectué par le stub de décompression","La restauration de l'IAT visible dès l'entrée du programme","Le retour de la fonction contenant l'AddressOfEntryPoint du fichier packé"],"answer":0,"explanation":"Le stub UPX décompresse en mémoire, restaure les registres (popad — miroir du pushad initial) puis effectue un grand saut vers l'OEP, dans une section auparavant vide (UPX0) maintenant peuplée de code réel. Poser un breakpoint sur ce transfert révèle l'OEP à dumper. GetProcAddress est appelé bien plus tôt, pendant la reconstruction de l'IAT.","tags":["unpacking","upx","oep","popad"],"optionNotes":["Apres popad, un grand saut quitte le stub vers UPX0 desormais peuplee : c'est l'OEP a dumper.","GetProcAddress est appele bien plus tot, pendant la reconstruction de l'IAT.","L'IAT est restauree par le stub avant l'OEP ; ce n'est pas le signal du transfert vers l'OEP.","L'EP du fichier packe est le debut du stub, pas l'OEP d'origine recherche."]},
  {"id":"re-convention-de-retour-des-structures","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"Convention de retour des structures","company":"Reversing: Secrets of Reverse Engineering ch.5","scenario":"Une fonction C renvoie une struct de 24 octets. À l'appel, l'analyste voit un pointeur supplémentaire passé avant les arguments visibles.","question":"Comment expliquer ce pointeur implicite dans la signature observée ?","options":["L'ABI passe un pointeur caché (RDI/premier argument) vers un tampon où l'appelé écrit la struct trop grande pour les registres","La fonction utilise thiscall et le pointeur est le this d'un objet C++","Le pointeur est l'adresse de retour dupliquée pour un mécanisme de sécurité","La struct est retournée dans RAX:RDX et le pointeur sert au nettoyage de pile"],"answer":0,"explanation":"Une struct trop grande pour tenir dans RAX(:RDX) est retournée en mémoire : l'appelant alloue un tampon et en passe l'adresse comme argument caché (premier registre d'arguments, RDI en System V / RCX en Windows x64), que l'appelé remplit ; RAX renvoie en général ce même pointeur. Ce paramètre implicite, sans contrepartie dans le code source, déroute l'analyse. Seules les petites structs (<= 16 octets en System V) transitent par RAX:RDX. Ce mécanisme d'ABI (retour par pointeur caché / sret) ne doit pas être confondu avec la NRVO, une optimisation de copie propre au C++.","tags":["calling-convention","struct-return","abi","x64"],"optionNotes":["Struct trop grande pour RAX:RDX : l'ABI passe un pointeur cache (1er registre) vers un tampon rempli par l'appele.","thiscall concerne le this d'un objet ; ici le pointeur cache est le tampon de retour (sret).","Ce n'est pas l'adresse de retour dupliquee, mais l'adresse du tampon de sortie.","Seules les petites structs transitent par RAX:RDX ; ici c'est un retour par pointeur en memoire."]},
  {"id":"re-graphe-de-flux-et-bloc-de-base","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"Graphe de flux et bloc de base","company":"The IDA Pro Book ch.9 — Cross-References and Graphing","question":"Dans un control flow graph, qu'est-ce qui définit précisément la fin d'un bloc de base ?","options":["Toute instruction de transfert de contrôle (saut, appel conditionnel/inconditionnel, retour) ou une cible de saut débutant un nouveau bloc","La première instruction accédant à la mémoire après une opération arithmétique","Chaque appel de fonction, qui découpe systématiquement le code en deux blocs","Une frontière tous les 16 octets imposée par l'alignement du désassembleur"],"answer":0,"explanation":"Un bloc de base est une séquence linéaire à une seule entrée et une seule sortie : il se termine sur une instruction de branchement (jmp/jcc/ret) ou juste avant une instruction cible d'un saut (qui commence un nouveau bloc). Les CALL ne rompent pas nécessairement le bloc (l'exécution revient), sauf conventions d'outil.","tags":["cfg","basic-block","ida","graphing"],"optionNotes":["Un bloc se termine sur un branchement (jmp/jcc/ret) ou juste avant une cible de saut qui ouvre un bloc.","Un acces memoire ne delimite pas un bloc de base ; c'est le flot de controle qui le fait.","Un CALL ne coupe pas forcement le bloc (l'execution revient), sauf convention d'outil.","Aucune frontiere fixe tous les 16 octets : la limite depend du flot de controle."]},
  {"id":"re-comparaison-de-chaines-obfusquee","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"Comparaison de chaînes obfusquée","company":"Practical Malware Analysis ch.15 — Anti-Disassembly","scenario":"jz  $+2\ndb 0E8h   ; octet parasite\n; le vrai code reprend ici","question":"Quelle technique anti-désassemblage illustre ce fragment ?","options":["Un saut conditionnel toujours pris vers un octet suivant, cachant un octet parasite qui désaligne le désassemblage linéaire","Un breakpoint logiciel déguisé en 0xE8 pour piéger les débogueurs","Un appel indirect chiffré dont la cible n'est révélée qu'à l'exécution","Une table de saut compressée que seul IDA en mode récursif peut résoudre"],"answer":0,"explanation":"C'est le motif classique du saut vers un opcode partiel : jz $+2 (ou un jz/jnz complémentaire toujours pris) enjambe un octet de camouflage (ici E8, début d'un CALL). Le désassembleur linéaire décode ce E8 comme instruction et se désynchronise, alors que le flot réel reprend après. Contre-mesure : forcer le réalignement à la vraie cible.","tags":["anti-disassembly","rogue-byte","obfuscation","alignment"],"optionNotes":["Un saut toujours pris enjambe un octet parasite (E8) : le linear sweep le decode et se desynchronise.","L'octet E8 est un camouflage (debut de CALL), pas un breakpoint logiciel (0xCC).","Il n'y a pas d'appel indirect chiffre : juste un octet de bourrage saute.","Aucune table de saut ici ; c'est un octet parasite qui desaligne le desassemblage."]},
  {"id":"re-eat-et-exports-d-une-dll","type":"mcq","domain":"software","topic":"reversing","difficulty":"intermediate","title":"EAT et exports d'une DLL","company":"The IDA Pro Book ch.14 — PE Files","question":"Que contient l'Export Address Table (EAT) d'une DLL ?","options":["Les RVA des fonctions/symboles que la DLL expose, indexés par ordinal ou par nom","Les adresses des fonctions que la DLL importe d'autres modules","La liste des relocations à appliquer si la DLL n'est pas chargée à sa base préférée","Les points d'entrée des gestionnaires d'exceptions enregistrés par la DLL"],"answer":0,"explanation":"L'EAT (dans le Export Directory) liste les RVA des fonctions exportées, accessibles par ordinal ou via la table de noms. C'est le pendant de l'IAT (côté imports). GetProcAddress consulte l'EAT pour résoudre un symbole demandé.","tags":["pe","eat","exports","dll"],"optionNotes":["L'EAT liste les RVA des fonctions exportees par la DLL, accessibles par ordinal ou par nom.","Les fonctions importees relevent de l'IAT, pas de l'EAT (cote exports).","Les relocations sont dans .reloc, pas dans l'Export Directory.","Les gestionnaires d'exceptions ne sont pas stockes dans l'EAT."]},
  {"id":"re-process-hollowing","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"Process hollowing","company":"Practical Malware Analysis ch.12 — Covert Malware Launching","scenario":"CreateProcess(..., CREATE_SUSPENDED) -> NtUnmapViewOfSection -> VirtualAllocEx -> WriteProcessMemory -> SetThreadContext -> ResumeThread","question":"Quelle technique cette séquence caractérise-t-elle ?","options":["Process hollowing : démapper l'image d'un process légitime suspendu et la remplacer par du code malveillant","Injection de DLL réflective dans un process déjà en cours d'exécution","Détournement de thread (thread hijacking) d'un process tiers non suspendu","Installation d'un hook inline global via une DLL AppInit"],"answer":0,"explanation":"Le hollowing crée un process légitime en CREATE_SUSPENDED, démappe son image d'origine (NtUnmapViewOfSection), alloue et écrit le code malveillant, ajuste le point d'entrée via SetThreadContext (EAX/RCX ou EIP/RIP), puis ResumeThread : le process porte un nom légitime mais exécute le payload. La présence de NtUnmapViewOfSection + SetThreadContext est la signature.","tags":["process-hollowing","injection","createprocess","malware"],"optionNotes":["CREATE_SUSPENDED + NtUnmapViewOfSection + SetThreadContext + ResumeThread = process hollowing.","L'injection reflective charge une DLL en memoire sans demapper l'image hote ni CREATE_SUSPENDED.","Le thread hijacking detourne un thread existant, sans demapper l'image ni la recreer suspendue.","Un hook AppInit charge une DLL globale via le registre, sans NtUnmapViewOfSection."]},
  {"id":"re-saut-vers-le-milieu-d-une-instruction","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"Saut vers le milieu d'une instruction","company":"Practical Malware Analysis ch.15 — Anti-Disassembly","question":"Pourquoi les instructions x86 chevauchantes (overlapping instructions) trompent-elles les désassembleurs ?","options":["L'ISA x86 étant à longueur variable et non alignée, un même flux d'octets se décode différemment selon l'offset de départ","Le processeur exécute plusieurs décodages en parallèle, ce qu'aucun désassembleur ne peut modéliser","Les instructions chevauchantes exigent le mode 64 bits, non géré en désassemblage linéaire","Elles reposent sur des préfixes de segment que les outils ignorent systématiquement"],"answer":0,"explanation":"En x86, les instructions ont une longueur variable et ne sont pas alignées : en démarrant le décodage à un offset différent, la même suite d'octets produit des instructions totalement différentes. Un attaquant fait sauter le flot au milieu d'une instruction apparente pour révéler un autre flux d'exécution que celui vu par le désassembleur.","tags":["anti-disassembly","overlapping-instructions","x86","obfuscation"],"optionNotes":["x86 est a longueur variable et non aligne : le meme flux se decode autrement selon l'offset de depart.","Le CPU ne fait pas 'plusieurs decodages paralleles' modelisables ; c'est l'ambiguite d'offset qui trompe.","Les instructions chevauchantes existent aussi en 32 bits ; ce n'est pas propre au mode 64 bits.","Le procede ne repose pas sur des prefixes de segment mais sur le decodage a un offset decale."]},
  {"id":"re-erreur-dans-un-parseur-d-en-tete-pe","type":"find-error","domain":"software","topic":"reversing","difficulty":"intermediate","title":"Erreur dans un parseur d'en-tête PE","company":"The IDA Pro Book ch.14 — PE Files","language":"python","code":"import struct\n\ndef get_pe_offset(data: bytes) -> int:\n    if data[0:2] != b\"MZ\":\n        raise ValueError(\"pas un MZ\")\n    # e_lfanew est un uint32 a l'offset 0x3C\n    e_lfanew = struct.unpack(\"<I\", data[0x3C:0x3E])[0]\n    return e_lfanew","question":"Quelle est l'erreur dans la lecture de e_lfanew ?","options":["La tranche data[0x3C:0x3E] ne fournit que 2 octets alors que <I lit un uint32 sur 4 octets ; il faut data[0x3C:0x40]","On doit lire e_lfanew en big-endian (>I) car les en-têtes PE sont en gros-boutiste","La signature à vérifier est b\"PE\\0\\0\" et non b\"MZ\" au début du fichier","struct.unpack renvoie un entier signé, il faudrait masquer avec & 0xFFFFFFFF"],"answer":0,"explanation":"e_lfanew est un DWORD (4 octets) à l'offset 0x3C, donc la tranche doit être data[0x3C:0x40] ; data[0x3C:0x3E] ne donne que 2 octets et struct lèvera une erreur (ou lira mal). Les structures PE sont little-endian (<I correct) ; MZ est bien la signature DOS de tête, PE\\0\\0 se trouve à l'offset pointé par e_lfanew.","tags":["pe","e_lfanew","python","parsing"],"optionNotes":["e_lfanew est un uint32 (4 octets) : la tranche doit etre data[0x3C:0x40], pas [0x3C:0x3E].","Les structures PE sont little-endian : <I est correct, pas >I.","MZ est bien la signature DOS en tete ; PE\\0\\0 est a l'offset pointe par e_lfanew.","e_lfanew est non signe et positif ; aucun masquage requis, le bug est la taille de tranche."]},
  {"id":"re-effet-du-bit-nx-dep","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"Effet du bit NX/DEP","company":"Practical Binary Analysis ch.5 — Exploitation basics","question":"En quoi l'activation du bit NX (DEP) a-t-elle fait évoluer les techniques d'exploitation ?","options":["La pile devenant non exécutable, l'injection de shellcode a cédé la place au réemploi de code (ROP/ret2libc)","Elle rend la pile non inscriptible, empêchant tout débordement de tampon","Elle chiffre les pages de code, obligeant à déchiffrer avant exécution","Elle randomise l'adresse de la pile, ce que seul l'ASLR complète"],"answer":0,"explanation":"NX/DEP marque les pages de données (pile, tas) comme non exécutables : un shellcode injecté sur la pile ne peut plus s'exécuter. Les attaquants se sont tournés vers le réemploi de code existant, exécutable (ret2libc puis ROP). NX n'empêche ni l'écriture ni le débordement ; la randomisation d'adresse relève de l'ASLR.","tags":["nx","dep","rop","exploitation"],"optionNotes":["NX marque pile/tas non executables : le shellcode injecte ne s'execute plus, d'ou ROP/ret2libc.","NX n'empeche ni l'ecriture ni le debordement ; il bloque seulement l'execution des donnees.","NX ne chiffre rien : il pose un attribut non executable sur les pages de donnees.","Randomiser l'adresse de la pile est le role de l'ASLR, pas du bit NX."]},
  {"id":"re-cdq-avant-idiv","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"cdq avant idiv","company":"Practical Binary Analysis ch.1 — Anatomy of a Binary","scenario":"mov eax, [ebp-4]\ncdq\nidiv dword ptr [ebp-8]","question":"Quel est le rôle de l'instruction cdq ici ?","options":["Étendre le signe d'EAX dans EDX pour former le dividende 64 bits EDX:EAX attendu par idiv signé","Copier EAX dans EDX afin de préserver l'opérande avant la division","Mettre EDX à zéro comme le ferait xor edx,edx avant une division non signée","Convertir EAX en flottant double précision avant l'opération arithmétique"],"answer":0,"explanation":"idiv (division signée) divise EDX:EAX par l'opérande. cdq étend le bit de signe d'EAX à travers tout EDX, construisant correctement le dividende 64 bits signé. Pour une division non signée (div), on mettrait plutôt EDX à zéro (xor edx,edx). Repérer cdq vs xor edx,edx révèle si l'opération est signée.","tags":["cdq","idiv","sign-extension","x86"],"optionNotes":["cdq propage le bit de signe d'EAX dans tout EDX, formant le dividende signe EDX:EAX qu'idiv attend.","cdq ne 'copie' pas EAX : il remplit EDX du signe d'EAX (0x00000000 ou 0xFFFFFFFF).","Mettre EDX a zero (xor edx,edx) prepare une division NON signee (div), pas idiv signe.","cdq est une extension de signe entiere, sans rapport avec les flottants."]},
  {"id":"re-detection-de-vmware-par-port-i-o","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"Détection de VMware par port I/O","company":"Practical Malware Analysis ch.17 — Anti-Virtual Machine Techniques","scenario":"mov eax, 'VMXh'\nmov ecx, 0Ah\nmov dx, 'VX'\nin eax, dx","question":"Quel mécanisme anti-VM ce code exploite-t-il ?","options":["Le canal de communication VMware (port 0x5658 'VX', magic 'VMXh') qui répond sous VMware et faute sur une machine réelle","Une lecture du numéro de série CPU exposant l'identifiant de l'hyperviseur","Un accès aux MSR de virtualisation VT-x révélant l'invité","Une temporisation via le port série pour mesurer la latence de la VM"],"answer":0,"explanation":"C'est le fameux backdoor VMware : EAX chargé du magic 'VMXh', DX = port 0x5658 ('VX'), l'instruction IN interroge le canal de communication invité-hôte. Sous VMware, EBX renvoie 'VMXh' ; sur une machine physique, IN sur ce port privilégié lève une exception. C'est un anti-VM spécifique, pas lié aux MSR ni au numéro de série.","tags":["anti-vm","vmware","port-io","backdoor"],"optionNotes":["Backdoor VMware : EAX='VMXh', DX=0x5658 ('VX'), IN interroge le canal invite-hote, qui faute sur une vraie machine.","Ce code n'accede pas a un numero de serie CPU mais au port de communication VMware.","Il n'interroge pas les MSR de virtualisation : c'est un port I/O proprietaire VMware.","Aucune mesure de latence via port serie ; c'est le canal backdoor 'VMXh'."]},
  {"id":"re-reconnaissance-d-un-switch-jump-table","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"Reconnaissance d'un switch/jump table","company":"The IDA Pro Book ch.8 — Datatypes and Data Structures","scenario":"cmp eax, 5\nja default_case\njmp dword ptr [jump_table + eax*4]","question":"Quelle construction de haut niveau ce code implémente-t-il et quel piège pose-t-il au désassemblage ?","options":["Un switch/case via table de sauts indirects ; les adresses de la table sont des données que le linear sweep peut mal décoder","Une boucle for déroulée dont chaque itération saute à un bloc distinct","Un appel virtuel C++ résolu via la vtable pointée par eax","Une chaîne de conditions if/else if convertie en saut binaire optimisé"],"answer":0,"explanation":"cmp/ja borne l'indice puis jmp [table + eax*4] indexe une table de pointeurs : c'est le pattern classique d'un switch dense compilé en jump table. La table est un bloc de données (RVA/adresses) souvent placé dans .text ou .rdata ; un désassembleur linéaire risque de la décoder comme du code et de se désaligner.","tags":["jump-table","switch","indirect-jump","disassembly"],"optionNotes":["cmp/ja borne l'indice puis jmp [table+eax*4] : switch dense en jump table, dont la table est de la donnee.","Ce n'est pas une boucle deroulee : un seul jmp indexe choisit la destination selon eax.","Un appel virtuel ferait call [vtable+off] via un objet ; ici c'est un jmp indexe par un indice.","Une chaine if/else compilerait en cmp/jcc successifs, pas en un unique jmp indexe par table."]},
  {"id":"re-anti-debug-closehandle-handle-invalide","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"Anti-debug CloseHandle / handle invalide","company":"Practical Malware Analysis ch.16 — Anti-Debugging","scenario":"Le programme appelle CloseHandle avec une valeur de handle manifestement invalide, sans gérer d'erreur.","question":"Comment cet appel peut-il détecter un débogueur ?","options":["Sous débogueur, fermer un handle invalide lève l'exception EXCEPTION_INVALID_HANDLE ; sans débogueur l'appel échoue silencieusement","CloseHandle sur un handle invalide libère un breakpoint matériel posé par le débogueur","L'appel force le débogueur à afficher sa fenêtre de handles, ralentissant l'exécution","Le handle invalide correspond au process de débogage, dont la fermeture le déconnecte"],"answer":0,"explanation":"Quand un process s'exécute sous débogueur, fermer un handle invalide via CloseHandle (ou NtClose) déclenche l'exception STATUS_INVALID_HANDLE ; hors débogueur, la fonction retourne simplement une erreur sans exception. Le malware place l'appel dans un try/except et déduit la présence du débogueur si l'exception survient.","tags":["anti-debug","closehandle","invalid-handle","exceptions"],"optionNotes":["Sous debogueur, fermer un handle invalide leve STATUS_INVALID_HANDLE ; hors debogueur, l'appel echoue sans exception.","CloseHandle ne 'libere' pas de breakpoint materiel (registres DR).","L'appel ne force aucune fenetre du debogueur ; c'est l'exception qui trahit.","Le handle invalide ne designe pas le process de debogage ; le test repose sur l'exception levee."]},
  {"id":"re-relocations-et-aslr","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"Relocations et ASLR","company":"The IDA Pro Book ch.14 — PE Files","question":"À quoi sert la section de relocation (.reloc) d'un PE et quel est son lien avec l'ASLR ?","options":["Elle liste les adresses codées en dur à ajuster si l'image n'est pas chargée à son ImageBase, rendant l'ASLR possible","Elle contient les adresses des imports à résoudre par le loader au démarrage","Elle stocke les points d'entrée alternatifs utilisés lors des mises à jour à chaud","Elle chiffre les adresses absolues pour empêcher leur lecture statique"],"answer":0,"explanation":"La table .reloc énumère les emplacements contenant des adresses absolues dépendant de la base de chargement ; si le loader place l'image ailleurs que l'ImageBase (comme l'exige l'ASLR), il applique le delta à chaque entrée. Un binaire sans .reloc (DYNAMICBASE absent) ne peut être relocalisé et échappe partiellement à l'ASLR. La résolution des imports relève de l'IAT, pas de .reloc.","tags":["pe","relocations","aslr","loader"],"optionNotes":[".reloc liste les adresses absolues a corriger si l'image n'est pas chargee a son ImageBase, permettant l'ASLR.","Resoudre les imports est le role de l'IAT, pas de .reloc.",".reloc ne stocke pas de points d'entree alternatifs pour du hot-patching.",".reloc ne chiffre rien : elle enumere des emplacements a reajuster."]},
  {"id":"re-pile-canari-et-stack-smashing","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"Pile canari et stack smashing","company":"Practical Binary Analysis ch.5 — Exploitation mitigations","scenario":"mov rax, fs:[0x28]\nmov [rbp-8], rax\n; ... corps ...\nmov rcx, [rbp-8]\nxor rcx, fs:[0x28]\njnz __stack_chk_fail","question":"Que réalise ce dispositif et comment un exploit doit-il en tenir compte ?","options":["Un canari de pile : la valeur de fs:[0x28] est vérifiée avant le ret ; l'attaquant doit préserver ou divulguer le canari","Un chiffrement de l'adresse de retour, à déchiffrer via fs:[0x28] avant tout détournement","Un compteur d'appels récursifs limitant la profondeur pour éviter l'épuisement de pile","Une sauvegarde des registres non volatils imposée par l'ABI System V"],"answer":0,"explanation":"fs:[0x28] contient le stack canary (référence thread-local) ; il est copié en tête de frame puis re-vérifié avant le retour (__stack_chk_fail si altéré). Un débordement écrasant l'adresse de retour corrompt le canari et fait avorter le programme : l'attaquant doit soit fuiter la valeur du canari (info leak) pour la réécrire à l'identique, soit éviter de l'écraser (ex. écriture ciblée).","tags":["stack-canary","stack-protector","exploitation","mitigations"],"optionNotes":["fs:[0x28] est le canari : copie en tete de frame puis reverifie avant ret ; il faut le fuiter ou l'eviter.","Le canari ne chiffre pas l'adresse de retour ; il detecte sa corruption par un debordement.","Ce n'est pas un compteur de recursion : c'est une valeur sentinelle controlee avant le retour.","La sauvegarde des registres non volatils est distincte ; fs:[0x28] est un stack canary."]},
  {"id":"re-fuite-via-use-after-free","type":"find-error","domain":"software","topic":"reversing","difficulty":"senior","title":"Fuite via use-after-free","company":"Practical Binary Analysis ch.5 — Memory corruption","language":"c","code":"#include <stdlib.h>\n#include <string.h>\n\nchar *build(const char *src) {\n    char *buf = malloc(32);\n    strncpy(buf, src, 31);\n    buf[31] = '\\0';\n    free(buf);\n    return buf;\n}\n\nvoid use(const char *s) {\n    char *p = build(s);\n    // ... le code appelant lit ensuite *p\n}","question":"Quel défaut mémoire ce code introduit-il ?","options":["build retourne buf après l'avoir free : l'appelant déréférence un pointeur libéré (use-after-free)","strncpy peut laisser buf non terminé, provoquant une lecture hors limites","malloc(32) est trop petit pour src, causant un débordement de tas","free(buf) est appelé deux fois, ce qui corrompt les métadonnées de l'allocateur"],"answer":0,"explanation":"build libère buf puis en retourne le pointeur ; toute lecture ultérieure via p est un use-after-free (mémoire pouvant être réallouée). Ici buf[31]='\\0' garantit la terminaison et malloc(32) + strncpy(...,31) ne déborde pas ; il n'y a qu'un seul free. Le défaut est de rendre puis d'utiliser un pointeur déjà libéré.","tags":["use-after-free","heap","memory-corruption","c"],"optionNotes":["build fait free(buf) puis retourne buf : toute lecture ulterieure via p est un use-after-free.","buf[31]='\\0' garantit ici la terminaison ; ce n'est pas le defaut.","malloc(32) + strncpy(...,31) + buf[31] tient dans 32 octets : pas de debordement de tas.","free n'est appele qu'une seule fois ; il n'y a pas de double free."]},
  {"id":"re-direction-flag-et-rep-movsb","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"Direction Flag et rep movsb","company":"Practical Binary Analysis ch.1 — Anatomy of a Binary","scenario":"cld\nmov ecx, 100h\nrep movsb","question":"Quel est l'effet précis de cette séquence et le rôle du cld initial ?","options":["cld met DF=0 pour que movsb progresse en avant ; rep movsb copie 0x100 octets de [esi] vers [edi]","cld efface le carry avant la copie ; rep movsb copie ECX mots de 4 octets","cld décrémente ESI/EDI ; rep movsb copie à rebours 0x100 octets","cld remet ECX à zéro puis rep movsb copie jusqu'au premier octet nul"],"answer":0,"explanation":"cld positionne le Direction Flag à 0, donc ESI et EDI s'incrémentent (copie vers l'avant). rep répète movsb ECX=0x100 fois, copiant 256 octets de [ESI] vers [EDI], en avançant. std (DF=1) ferait la copie à rebours. movsb traite des octets, pas des dwords.","tags":["direction-flag","rep-movsb","string-ops","x86"],"optionNotes":["cld met DF=0 (progression avant) ; rep movsb copie ECX=0x100 octets de [esi] vers [edi].","cld agit sur DF, pas sur le carry ; movsb copie des octets, pas des mots de 4 octets.","DF=0 fait INCREMENTER ESI/EDI (avant) ; c'est std (DF=1) qui va a rebours.","cld ne touche pas ECX ; rep repete exactement ECX fois, sans s'arreter sur un octet nul."]},
  {"id":"re-tls-callbacks-avant-le-point-d-entree","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"TLS callbacks avant le point d'entrée","company":"Practical Malware Analysis ch.16 — Anti-Debugging","question":"Pourquoi les TLS callbacks d'un PE sont-ils un endroit prisé pour du code anti-analyse ?","options":["Ils s'exécutent avant l'entry point, donc avant qu'un analyste posant un breakpoint sur l'EP ne prenne la main","Ils s'exécutent en ring 0, échappant aux débogueurs user-land","Ils sont chiffrés par défaut et déchiffrés uniquement sous exécution normale","Ils ne sont jamais listés dans l'en-tête PE, restant invisibles aux outils"],"answer":0,"explanation":"Les callbacks TLS (Thread Local Storage) sont invoqués par le loader AVANT l'AddressOfEntryPoint. Un analyste qui place son premier breakpoint sur l'entry point manque donc du code (anti-debug, déchiffrement, bombe logique) déjà exécuté dans le TLS callback. Ils figurent pourtant bien dans le Data Directory (TLS), donc repérables si on pense à les vérifier.","tags":["tls-callback","anti-debug","pe","entry-point"],"optionNotes":["Les TLS callbacks sont executes par le loader AVANT l'entry point, donc avant un BP pose sur l'EP.","Ils s'executent en ring 3, comme le reste du process, pas en ring 0.","Les TLS callbacks ne sont pas chiffres par defaut ; leur interet est leur execution precoce.","Ils figurent dans le Data Directory TLS du PE : reperables si l'on pense a les verifier."]},
  {"id":"re-reconnaitre-un-appel-via-vtable-c","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"Reconnaître un appel via vtable C++","company":"The IDA Pro Book ch.8 — Datatypes and Data Structures","scenario":"mov rax, [rcx]\ncall qword ptr [rax + 0x10]","question":"Que suggère fortement ce motif d'appel indirect en double indirection ?","options":["Un appel de méthode virtuelle C++ : [rcx] charge le pointeur de vtable, +0x10 sélectionne la 3e entrée","Un appel via l'IAT, rcx pointant la table des imports du module","Un saut de trampoline vers une fonction hookée en inline","Un appel de rappel (callback) stocké dans une variable locale à l'offset 0x10"],"answer":0,"explanation":"En x64 (Windows, RCX=this), [rcx] déréférence le premier champ de l'objet, généralement le pointeur vers la vtable ; call [rax+0x10] appelle la fonction à l'offset 0x10 de cette table, soit la 3e méthode virtuelle (index 2 en pointeurs de 8 octets). Cette double indirection this->vtable->method est la signature d'un appel virtuel C++.","tags":["cpp","vtable","virtual-call","reversing"],"optionNotes":["[rcx] charge le pointeur de vtable de l'objet, call [rax+0x10] appelle la 3e methode virtuelle : appel virtuel C++.","Un appel via l'IAT ferait call [table_imports] en simple indirection, pas this vers vtable vers methode.","Un trampoline inline saute vers une fonction hookee, sans cette double indirection via un objet.","Ce n'est pas un callback en variable locale : rcx pointe un objet dont on suit la vtable."]},
  {"id":"re-difference-plt-vs-plt-sec-cet-bind-now","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"Différence PLT vs PLT.sec (CET/BIND_NOW)","company":"Practical Binary Analysis ch.2 — The ELF Format","question":"Sur un binaire lié en Full RELRO / BIND_NOW, en quoi le comportement de la GOT diffère-t-il du lazy binding ?","options":["Toutes les entrées GOT sont résolues au chargement puis la GOT est passée en lecture seule, bloquant l'écrasement de pointeurs","La GOT est supprimée et remplacée par des appels directs codés en dur à l'édition de liens","La résolution reste paresseuse mais chaque entrée est chiffrée par une clé de chargement","La PLT disparaît entièrement, les fonctions étant inlinées dans chaque appelant"],"answer":0,"explanation":"Avec BIND_NOW (Full RELRO), le loader résout tous les symboles au démarrage puis remappe la GOT (et .got.plt) en lecture seule via GNU_RELRO : un attaquant ne peut plus réécrire une entrée GOT pour détourner le flot (contrairement au lazy binding où .got.plt reste inscriptible). La PLT subsiste comme stubs d'appel.","tags":["elf","relro","got","bind-now"],"optionNotes":["BIND_NOW/Full RELRO resout toute la GOT au chargement puis la remappe en lecture seule, bloquant l'ecrasement de pointeurs.","La GOT n'est pas supprimee : elle est resolue tot puis figee en lecture seule.","Avec BIND_NOW la resolution n'est plus paresseuse ; les entrees ne sont pas 'chiffrees'.","La PLT subsiste comme stubs d'appel ; les fonctions ne sont pas inlinees."]},
  {"id":"re-idiome-de-mise-a-zero-et-eflags","type":"mcq","domain":"software","topic":"reversing","difficulty":"senior","title":"Idiome de mise à zéro et EFLAGS","company":"Reversing: Secrets of Reverse Engineering ch.2","scenario":"xor eax, eax","question":"Outre la mise à zéro d'EAX, quel effet secondaire cette instruction produit-elle et pourquoi les compilateurs la préfèrent-ils à mov eax, 0 ?","options":["Elle met ZF=1 (et efface CF/OF) tout en produisant un encodage plus court, sans dépendance sur la valeur précédente d'EAX","Elle préserve tous les drapeaux et occupe le même nombre d'octets que mov eax,0","Elle met CF=1 pour signaler le passage à zéro, exploité par le saut suivant","Elle bloque le renommage de registre du CPU, garantissant l'ordre d'exécution"],"answer":0,"explanation":"xor eax,eax met EAX à zéro sur 2 octets (contre 5 pour mov eax,0) et affecte les flags : ZF=1, CF=OF=0. Les CPU modernes reconnaissent cet idiome comme zeroing (rupture de dépendance, pas de lecture de l'ancienne valeur), d'où sa préférence. mov eax,0 ne toucherait pas les flags mais est plus long et crée une fausse dépendance apparente.","tags":["xor","zeroing","eflags","optimization"],"optionNotes":["xor eax,eax met EAX=0, pose ZF=1 (CF=OF=0) sur 2 octets, sans lire l'ancienne valeur (rupture de dependance).","xor MODIFIE les flags et tient sur 2 octets, contre 5 pour mov eax,0 : ni flags preserves ni meme taille.","xor eax,eax met CF=0, pas CF=1 ; le resultat nul leve ZF, pas le carry.","Le CPU reconnait l'idiome comme zeroing (dependance rompue), il ne 'bloque' pas le renommage."]},
];
